			/*
			 * 서치 인풋에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onSipb1Click(e) {
			    var sipb1 = e.control;
			    
			    var voDsUseTaskSysSeCd = app.lookup("dsUseTaskSysSeCd");
			    var values = [];
			    
			    voDsUseTaskSysSeCd.getRowDataRanged().forEach(function(rowData) {
			        values.push(rowData["UNT_TASKWK_SE_CD"]);
			    });
			    
			    var voInitValue = {
			        BBSCTT_TYPE_SE_CD: msBbscttTypeSeCd,
			        UNITY_BBSCTT_CTGRYB_SE_CD: util.DataSet.getValue(app, "dsBoardDtlList", 0, "UNITY_BBSCTT_CTGRYB_SE_CD"),
			        VALUES: values
			    }
			    
			    util.Dialog.open(app, "app/exam/demo/itgBrd/itgNtcCmn/itgNtcCmnSysCdPop", "공지 기관", 440, 540, function( /*cpr.events.CUIEvent*/ e) {
			        
			        /*
			         * 다이얼로그 close 이벤트 핸들러(닫기 동작시 반환되는 값에 대한 처리)
			         * 다이얼로그가 이미 닫혀진 상태이기 때문에 다이얼로그 관련 이벤트리스너는 발생하지 않습니다.
			         */
			        /**@type cpr.controls.Dialog*/
			        var dialog = e.control;
			        var returnValue = dialog.returnValue;
			        
			        if (!ValueUtil.isNull(returnValue)) {
			            var vaTaskWkNms = returnValue["UNT_TASKWK_SE_NMS"];
			            var vaTaskWkCds = returnValue["UNT_TASKWK_SE_CDS"];
			            var vsCtgrybSeCd = returnValue["CTGRYB_SE_CD"];
			            var vsCtgrybSeNm = returnValue["CTGRYB_SE_NM"];
			            
			            sipb1.value = vaTaskWkNms.toString().replace(/ /g, "");
			            
			            // 사용 시스템 전체 제거
			            voDsUseTaskSysSeCd.clearData();
			            
			            vaTaskWkCds.forEach(function(taskwkSeCd, idx) {
			                voDsUseTaskSysSeCd.addRowData({
			                    UNITY_BBSCTT_ESNTAL_NO: mnBrdSeq,
			                    UNT_TASKWK_SE_CD: taskwkSeCd,
			                    UNT_TASKWK_SE_NM: vaTaskWkNms[idx]
			                });
			            });
			            
			            // 1개 이상의 단위 시스템을 선택했거나 선택한 업무가 단위업무에 포함되지 않을때 표시            
			            var voFindRow = app.lookup("dsCmbCtgrybSeCd").findFirstRow("CMMNS_CD_VALUE == '" + vsCtgrybSeCd + "'");
			            
			            if (vaTaskWkCds.length > 1 || !voFindRow) {
			                setGrpCtgrybSeCd(false, vsCtgrybSeNm);
			            } else {
			                setGrpCtgrybSeCd(true);
			            }
			            
			            app.lookup("cmbCtgrybSeCd").value = vsCtgrybSeCd;
			        }
			        
			    }, voInitValue);
			}

