			function dowloadHtml(htmlContent, htmlTitle, fimeNm){
			    var blod = new Blob(["제목 : " + htmlTitle + "<br/>", "내용 : " + "<br/>" + htmlContent], {
			        type:'text/html'
			    });
			    
			    var url = URL.createObjectURL(blod);
			    
			    var a = document.createElement("a");
			    a.href = url;
			    a.download = fimeNm;
			    
			    document.body.appendChild(a);
			    
			    a.click();
			    
			    document.body.removeChild(a);
			    URL.revokeObjectURL(url);
			        
			}
